"""The two queue CSVs are generated by scripts/build_queues.py and committed. Their dates
must be the ones the generator's own constants produce, or a re-run after the corpus
changes silently rewrites the calendar (2026-10-18: notes/queue.csv had been moved to
2026-10-12 by hand while NOTES_START still said 2026-11-16).

Run: python3 -m unittest discover -s tests
"""
import csv
import datetime as dt
import importlib.util
import os
import unittest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
spec = importlib.util.spec_from_file_location("build_queues", os.path.join(ROOT, "scripts", "build_queues.py"))
bq = importlib.util.module_from_spec(spec)
spec.loader.exec_module(bq)


def rows(path):
    with open(os.path.join(ROOT, path), newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


class QueueDates(unittest.TestCase):
    def test_notes_run_daily_from_notes_start(self):
        q = rows("notes/queue.csv")
        self.assertEqual(len(q), 90)
        for i, r in enumerate(q):
            self.assertEqual(r["day"], str(i + 1))
            self.assertEqual(r["date"], (bq.NOTES_START + dt.timedelta(days=i)).isoformat(), f"day {i + 1}")

    def test_archive_runs_weekly_from_archive_start_on_mondays(self):
        q = rows("archive/queue.csv")
        self.assertEqual(len(q), 52)
        self.assertEqual(bq.ARCHIVE_START.weekday(), 0)
        for i, r in enumerate(q):
            self.assertEqual(r["week"], str(i + 1))
            self.assertEqual(r["date"], (bq.ARCHIVE_START + dt.timedelta(weeks=i)).isoformat(), f"week {i + 1}")

    def test_blood_meridian_pin_lands_on_a_queue_week(self):
        q = rows("archive/queue.csv")
        for title, date in bq.PIN.items():
            hit = [r for r in q if r["title"] == title]
            self.assertEqual(len(hit), 1, title)
            self.assertEqual(hit[0]["date"], date.isoformat())
            self.assertEqual((date - bq.ARCHIVE_START).days % 7, 0)


if __name__ == "__main__":
    unittest.main()
